package world

import (
	"embed"
	"encoding/json"
	"math"
	"regexp"
	"sort"
	"strings"
	"unicode"

	"golang.org/x/text/unicode/norm"

	"github.com/myahse/babi-life/backend/internal/game"
)

// Every place of a commune, from OpenStreetMap: the maquis, boutiques,
// couturiers, salons, churches, mosques, schools, pharmacies… named on the
// map inside the commune's boundary (thousands in Yopougon). They're
// generated by tools/places/build.mjs and embedded here. They aren't in the
// world payload (it would weigh megabytes): the app asks for those around
// the Sim (GET /places). The hand-made places of world.go stay the
// commune's landmarks; a map point that is one of them is left out.

//go:embed osm/*.json
var osmFiles embed.FS

// OSMSource is the provenance shared by every place from the map.
var OSMSource = &game.Source{
	Status:  game.StatusPartial,
	URLs:    []string{"https://www.openstreetmap.org/copyright", "https://openfreemap.org/"},
	Checked: game.Checked,
	Note:    "Nom, type et position d'après OpenStreetMap (contributeurs, ODbL). Vérifié par la communauté, pas un par un par le jeu ; le type de lieu du jeu est déduit de celui de la carte.",
}

type osmFile struct {
	Commune string  `json:"commune"`
	Fetched string  `json:"fetched"`
	Places  [][]any `json:"places"` // id, name, kind, lat, lng, quarter, type
}

// MapPlace is a place from the map, as the app gets it.
type MapPlace struct {
	ID      string  `json:"id"`
	Name    string  `json:"name"`
	Kind    string  `json:"kind"`
	Lat     float64 `json:"lat"`
	Lng     float64 `json:"lng"`
	Quarter string  `json:"quarter,omitempty"`
	// Type is what the map calls it (kiosk, tailor, christian…).
	Type string `json:"type,omitempty"`
	// Faith: a place of worship's (game.FaithOf).
	Faith string `json:"faith,omitempty"`
}

var (
	mapPlaces  = map[string][]MapPlace{} // by commune
	mapByID    = map[string]MapPlace{}
	mapCommune = map[string]string{} // place id → commune id
	mapFetched = map[string]string{}
)

func init() {
	// The hand-made places of worship: their faith from their name.
	for i := range Cities {
		for j := range Cities[i].Communes {
			for k := range Cities[i].Communes[j].Places {
				if p := &Cities[i].Communes[j].Places[k]; p.Kind == "worship" && p.Faith == "" {
					p.Faith = game.FaithOf(p.Name, "")
				}
			}
		}
	}
	entries, err := osmFiles.ReadDir("osm")
	if err != nil {
		panic(err)
	}
	for _, e := range entries {
		raw, err := osmFiles.ReadFile("osm/" + e.Name())
		if err != nil {
			panic(err)
		}
		var f osmFile
		if err := json.Unmarshal(raw, &f); err != nil {
			panic("osm/" + e.Name() + ": " + err.Error())
		}
		cm, ok := communeByID(f.Commune)
		if !ok {
			panic("osm/" + e.Name() + ": unknown commune " + f.Commune)
		}
		var worship []MapPlace
		for _, row := range f.Places {
			p := MapPlace{ID: row[0].(string), Name: InGameName(row[1].(string)), Kind: row[2].(string), Lat: row[3].(float64), Lng: row[4].(float64), Quarter: row[5].(string)}
			if t, ok := row[6].(string); ok {
				p.Type = t
			}
			if _, ok := game.Kinds[p.Kind]; !ok {
				panic("osm/" + e.Name() + ": unknown kind " + p.Kind + " for " + p.ID)
			}
			if p.Kind == "worship" {
				p.Name = worshipName(p.Name)
				if notWorship.MatchString(p.Name) {
					continue
				}
				p.Faith = game.FaithOf(p.Name, p.Type)
			}
			if curated(cm, p) {
				continue
			}
			if p.Kind == "worship" {
				worship = append(worship, p)
				continue
			}
			mapPlaces[f.Commune] = append(mapPlaces[f.Commune], p)
		}
		mapPlaces[f.Commune] = append(mapPlaces[f.Commune], onceEach(worship)...)
		for _, p := range mapPlaces[f.Commune] {
			mapByID[p.ID] = p
			mapCommune[p.ID] = f.Commune
		}
		mapFetched[f.Commune] = f.Fetched
	}
	// Each commune's count of them, for its number of places (the map's card, « Où aller »).
	for i := range Cities {
		for j := range Cities[i].Communes {
			Cities[i].Communes[j].MapCount = len(mapPlaces[Cities[i].Communes[j].ID])
		}
	}
}

// The real brands go by their names in the game (« Babi » is a story, not
// an ad): the bus company is the SITRA, the fried chicken CFC, the big hotel
// of Cocody the Softitel. Whole words only, whatever the case on the map.
var brands = []struct {
	re   *regexp.Regexp
	name string
}{
	{regexp.MustCompile(`(?i)\bSOTRA\b`), "SITRA"},
	{regexp.MustCompile(`(?i)\bKFC\b`), "CFC"},
	{regexp.MustCompile(`(?i)\bKentucky Fried Chicken\b`), "CFC"},
	{regexp.MustCompile(`(?i)\bSofitel\b`), "Softitel"},
}

// InGameName is a map name with the real brands renamed.
func InGameName(name string) string {
	for _, b := range brands {
		name = b.re.ReplaceAllString(name, b.name)
	}
	return name
}

// Places of worship as the map has them, all of them (a dense commune has a
// church or a mosque at every corner: they all stay), but misspelt
// (« Mosquéu », « mosqée », « Eglie »), some twice a few metres apart, a
// school among them. The game spells them right, keeps each named one once,
// and leaves the schools out.

// The words of a place's name the map misspells, by how it writes them (lower case).
var worshipWords = map[string]string{"mosquéu": "Mosquée", "mosqée": "Mosquée", "mosqué": "Mosquée", "mosque": "Mosquée", "mosquee": "Mosquée", "eglie": "Église", "eglise": "Église", "eglises": "Églises"}

// worshipName: the name spelt right, its shouted words (NOUROULOUDHA) in
// ordinary case (short ones are initials: CMA, MIEDA), its first letter up.
func worshipName(name string) string {
	words := strings.Fields(name)
	for i, w := range words {
		if fixed, ok := worshipWords[strings.ToLower(w)]; ok {
			words[i] = fixed
			continue
		}
		if r := []rune(w); len(r) >= 6 && strings.ToUpper(w) == w && strings.ToLower(w) != w {
			words[i] = string(r[0]) + strings.ToLower(string(r[1:]))
		}
	}
	if r := []rune(strings.Join(words, " ")); len(r) > 0 {
		return string(unicode.ToUpper(r[0])) + string(r[1:])
	}
	return name
}

// The words that alone don't name a place (« Eglise Evangelique », « Mission »).
var worshipGeneric = map[string]bool{"eglise": true, "eglises": true, "evangelique": true, "mosquee": true, "mission": true, "temple": true, "chapelle": true, "protestante": true}

var notWorship = regexp.MustCompile(`(?i)groupe scolaire|école|ecole|collège|college|lycée|lycee`)

// named: the name says which one it is (« Église Parole de Vie »), not only what it is (« Eglise Evangelique »).
func named(name string) bool {
	for w := range nameWords(name) {
		if !worshipGeneric[w] {
			return true
		}
	}
	return false
}

// onceEach: a named place once (the same name within 300 m is the same
// place); the nameless ones (« Église », « Mosquée ») are as many places as
// the map has.
func onceEach(all []MapPlace) []MapPlace {
	var once []MapPlace
	for _, p := range all {
		pw := nameWords(p.Name)
		dup := false
		if named(p.Name) {
			for _, o := range once {
				if sameWords(pw, nameWords(o.Name)) && distKm(o.Lat, o.Lng, p.Lat, p.Lng) < 0.3 {
					dup = true
					break
				}
			}
		}
		if !dup {
			once = append(once, p)
		}
	}
	return once
}

func sameWords(a, b map[string]bool) bool {
	if len(a) != len(b) {
		return false
	}
	for w := range a {
		if !b[w] {
			return false
		}
	}
	return true
}

func communeByID(id string) (Commune, bool) {
	for _, c := range Cities {
		for _, cm := range c.Communes {
			if cm.ID == id {
				return cm, true
			}
		}
	}
	return Commune{}, false
}

// curated: the map point is one of the commune's hand-made places (same
// kind of name, within 400 m): the hand-made one stays, with its sources.
// A place of another kind only when it has the very name: the town's name
// in both was enough before, and the Pharmacie Saint-André went with the
// Église Saint-André, the commissariat of Grand-Bassam with its mairie.
func curated(cm Commune, p MapPlace) bool {
	pw := nameWords(p.Name)
	for _, c := range cm.Places {
		if distKm(c.Lat, c.Lng, p.Lat, p.Lng) > 0.4 {
			continue
		}
		cw := nameWords(c.Name)
		if len(cw) == 0 || len(pw) == 0 {
			continue
		}
		shared := 0
		for w := range cw {
			if pw[w] {
				shared++
			}
		}
		if c.Kind != p.Kind {
			if shared == len(cw) && shared == len(pw) {
				return true
			}
			continue
		}
		if float64(shared) >= 0.6*float64(min(len(cw), len(pw))) {
			return true
		}
	}
	return false
}

var stopWords = map[string]bool{"de": true, "du": true, "des": true, "la": true, "le": true, "les": true, "l": true, "d": true, "et": true, "a": true, "au": true, "yopougon": true}

func nameWords(s string) map[string]bool {
	// The accents off first (« é » is « e » and its mark, which isn't a letter: split on, « église » was « e », « glise »).
	t := strings.Map(func(r rune) rune {
		if unicode.Is(unicode.Mn, r) {
			return -1
		}
		return r
	}, norm.NFD.String(strings.ToLower(s)))
	out := map[string]bool{}
	for _, w := range strings.FieldsFunc(t, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) }) {
		if !stopWords[w] {
			out[w] = true
		}
	}
	return out
}

func distKm(lat1, lng1, lat2, lng2 float64) float64 {
	dy := (lat2 - lat1) * 111.32
	dx := (lng2 - lng1) * 111.32 * math.Cos((lat1+lat2)/2*math.Pi/180)
	return math.Hypot(dx, dy)
}

// MapPlacesNear: a commune's map places within r km of a point, nearest
// first, at most limit of them.
func MapPlacesNear(commune string, lat, lng, r float64, limit int) []MapPlace {
	type near struct {
		p MapPlace
		d float64
	}
	var all []near
	for _, p := range mapPlaces[commune] {
		if d := distKm(lat, lng, p.Lat, p.Lng); d <= r {
			all = append(all, near{p, d})
		}
	}
	sort.Slice(all, func(i, j int) bool { return all[i].d < all[j].d })
	if len(all) > limit {
		all = all[:limit]
	}
	out := make([]MapPlace, len(all))
	for i, n := range all {
		out[i] = n.p
	}
	return out
}

// SearchMapPlaces: a commune's map places whose name or quarter has all
// these words, at most limit of them (for "Où aller ?").
func SearchMapPlaces(commune, q string, limit int) []MapPlace {
	want := nameWords(q)
	if len(want) == 0 {
		return nil
	}
	var out []MapPlace
	for _, p := range mapPlaces[commune] {
		have := nameWords(p.Name + " " + p.Quarter)
		ok := true
		for w := range want {
			found := false
			for h := range have {
				if strings.HasPrefix(h, w) {
					found = true
					break
				}
			}
			if !found {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, p)
			if len(out) >= limit {
				break
			}
		}
	}
	return out
}

// MapPlaceByID: one map place.
// Commissariats: the commune's police stations on the map (« Commissariat
// du 16ᵉ Arrondissement »…), gendarmeries left out, by name.
func Commissariats(commune string) []MapPlace {
	var out []MapPlace
	for _, p := range mapPlaces[commune] {
		if p.Kind == "police" && strings.Contains(strings.ToLower(p.Name), "commissariat") {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func MapPlaceByID(id string) (MapPlace, bool) {
	p, ok := mapByID[id]
	return p, ok
}

// MapPlaceCount: how many map places a commune has.
func MapPlaceCount(commune string) int { return len(mapPlaces[commune]) }

// MapPlacesOf: all the commune's places from the map, up to limit (a commune with a few hundred: its whole list).
func MapPlacesOf(commune string, limit int) []MapPlace {
	all := mapPlaces[commune]
	return all[:min(len(all), limit)]
}

// mapPlace finds a map place by id, as a world Place.
func mapPlace(id string) (City, Commune, Place, bool) {
	p, ok := mapByID[id]
	if !ok {
		return City{}, Commune{}, Place{}, false
	}
	for _, c := range Cities {
		for _, cm := range c.Communes {
			if cm.ID == mapCommune[id] {
				return c, cm, Place{ID: p.ID, Name: p.Name, Kind: p.Kind, Lat: p.Lat, Lng: p.Lng, Quarter: p.Quarter, Real: true, Source: OSMSource, Faith: p.Faith}, true
			}
		}
	}
	return City{}, Commune{}, Place{}, false
}

// CommuneIDs: every commune of the game, by id (« yopougon », « cocody »…).
func CommuneIDs() map[string]bool {
	out := map[string]bool{}
	for _, c := range Cities {
		for _, cm := range c.Communes {
			out[cm.ID] = true
		}
	}
	return out
}
